-- 11/11/2026 — chủ shop gửi ảnh racekit + bảng giá vé Sa Đéc Flower Half Marathon 2026, đăng chuyên mục Tin tức & Sự kiện.
INSERT INTO "posts" ("slug", "kind", "category", "title", "excerpt", "body", "cover_file", "read_minutes", "author_name", "diseases", "tags",
